{
  "technical_and_design_decisions": [
    "Aggregated progress for composed jobs will be computed by summing child job step execution progress exposed via existing JobService, and rendered as a text progress bar in the Spring XD shell and REST response.",
    "Restart of composed jobs will reuse the existing Spring Batch/Spring XD job restart mechanism, re-launching child jobs in original order with the same parameters.",
    "Kafka 0.9 integration investigation will evaluate the existing spring-cloud-stream binder for Kafka against the 0.9 client API and document gaps; no production code changes are required for this increment.",
    "Lattice bare-metal deployment will be explored by creating Docker images for s-c-d components and bootstrap scripts using the Lattice `ltc` CLI, documenting network and volume requirements.",
    "Dot-delimited property syntax will be implemented by extending the stream definition parser to treat dots as nested paths for Tuple and JSON property resolvers, while keeping backward compatibility with flat keys.",
    "Shell tab completion will be implemented using Spring Shell's CompletionProvider interface, querying the module registry for module names and option metadata.",
    "Mesos deployment will be supported via Marathon application definitions and documentation, assuming a running Mesos/Marathon cluster; no custom Mesos framework code is required.",
    "The Redis test @Rule will be extracted into a new standalone Git repository with a Gradle build, published to the existing artifact repository, and consumed as a test dependency.",
    "All new code will follow the existing Spring coding conventions and will be written in Java, targeting the Java LTS version already used by the project."
  ],
  "assumptions": [
    "The developer is already familiar with the Spring XD and Spring Cloud Data Flow codebases and has a working development environment.",
    "User stories U3 and U4 are investigative spikes; deliverables are reports and proof-of-concept scripts, not full production features.",
    "The term 'XD user' and 's-c-d user' refer to users of the Spring XD / Spring Cloud Data Flow shell and UI; both will be updated where applicable.",
    "Existing CI pipelines and artifact repositories can be extended for the new Redis test fixtures repo without significant extra work.",
    "Effort estimates are for a single developer performing all tasks, measured in ideal workdays (8 hours), and exclude holidays, meetings, and unrelated support.",
    "The specification lacks precise UI details; a simple text-based progress bar and standard shell completion are assumed."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Requirements analysis and detailed design",
      "activity_description": "Review user stories U1-U8, define technical approach, design data models and interfaces for composed job progress/restart, shell tab completion, property resolution, Mesos deployment, Redis rule extraction, and spikes for Kafka/Lattice.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement aggregated progress bar for composed jobs",
      "activity_description": "Extend job service to compute aggregate progress from child job executions; add REST endpoint and shell/UI rendering of progress bar for composed jobs in Spring XD.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Support restart of composed jobs",
      "activity_description": "Implement restart logic for composed jobs, including persistence of composition structure, re-launch of failed/completed child jobs via shell/UI command.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Investigate Kafka 0.9 integration options",
      "activity_description": "Spike to evaluate Spring Cloud Data Flow integration with Kafka 0.9 client, identify compatibility issues and improvement areas; produce findings document.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Explore Lattice infrastructure bootstrap for bare metal",
      "activity_description": "Research and prototype bootstrap scripts for deploying s-c-d on Lattice bare metal; evaluate networking and service discovery; produce recommendations.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Implement dot-delimited property resolution for Tuple/JSON",
      "activity_description": "Enhance stream definition parser to support dot-delimited keys (e.g., tuple.field=value) resolving to nested Tuple/JSON properties; add unit tests.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Implement shell tab completion for modules/options",
      "activity_description": "Extend Spring Cloud Data Flow shell with completion providers for module names and their configurable options using Spring Shell's completion API.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Enable s-c-d deployment on Mesos",
      "activity_description": "Create deployment artifacts, Marathon app definitions or Mesos scheduler integration, documentation for running s-c-d on Mesos cluster.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Extract Redis test rule to separate repository",
      "activity_description": "Refactor Redis JUnit @Rule into new standalone project, set up Gradle/Maven build, publish artifact, update references in s-c-d projects.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration testing and QA",
      "activity_description": "Perform end-to-end testing of all new features, fix defects, ensure CI passes for all affected modules.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Documentation and release activities",
      "activity_description": "Write user docs for progress bar, restart, tab completion, dot syntax, Mesos deployment; cut release/tag version; update README and migration notes.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 44
  }
}

